/**
 * Data Transfer Objects (DTOs).
 *
 * Contract types here mirror Pydantic models in
 * ``apps/api/src/core/schemas.py``. The auto-generated ``dto.generated.ts``
 * (produced by ``make generate-api`` from FastAPI's OpenAPI schema) is
 * the authoritative reference — when schemas.py changes, regenerate
 * dto.generated.ts and reconcile every drift in this file by hand.
 *
 * Frontend-private types (SSE event shapes, internal enums, importer
 * payloads, view discriminators) intentionally do NOT live in the
 * OpenAPI schema and are hand-written here.
 *
 * DO NOT EDIT THIS FILE WITHOUT VERIFYING IT MATCHES dto.generated.ts.
 * Two shapes no longer need that verification because they ARE the
 * generated type: `MeetStandingRowDTO` (here) and `StandingRowDTO`
 * (bracketDto.ts).
 */

// SP-DM-3 P1: the two standings row shapes are taken from the generated
// OpenAPI types rather than hand-mirrored (R-DM-9(c), applied to the shapes
// whose divergence count is already zero). A generated alias cannot drift, so
// these two need no parity entry - see api/__tests__/dtoParity.test.ts.
import type { components } from './dto.generated';

// Tournament Configuration
export interface TournamentConfig {
  // Human-readable name. Used as a slug in backup filenames and as
  // the headline on the public TV display. Optional — when unset,
  // chrome falls back to "Tournament" / "tournament-<timestamp>".
  tournamentName?: string;
  // Per-tournament meet mode.
  //
  //   ``dual`` — exactly two schools play each other. The default.
  //   ``tri``  — three schools, full round-robin: every pair (A-B,
  //              A-C, B-C) plays each event TWICE so combined results
  //              decide the meet. Every individual match is still A
  //              vs B (one side per side, like dual) — there is no
  //              such thing as a "1v1v1" match in badminton.
  //
  // The auto-match generator branches on this; rendering surfaces
  // do not (matches always render as A vs B regardless of mode).
  meetMode?: 'dual' | 'tri';
  intervalMinutes: number;
  dayStart: string; // HH:mm format
  dayEnd: string; // HH:mm format
  tournamentDate?: string; // ISO date string: "2026-02-15"
  breaks: BreakWindow[];
  courtCount: number;
  defaultRestMinutes: number;
  freezeHorizonSlots: number;
  rankCounts?: Record<string, number>; // {"MS": 3, "WS": 3, "MD": 2, "WD": 4, "XD": 2}
  enableCourtUtilization?: boolean;
  courtUtilizationPenalty?: number;
  // Game proximity constraint
  enableGameProximity?: boolean;
  minGameSpacingSlots?: number | null;
  maxGameSpacingSlots?: number | null;
  gameProximityPenalty?: number;
  // Compact schedule - minimize makespan or eliminate gaps
  enableCompactSchedule?: boolean;
  compactScheduleMode?: 'minimize_makespan' | 'no_gaps' | 'finish_by_time';
  compactSchedulePenalty?: number;
  targetFinishSlot?: number | null;
  // Allow player overlap
  allowPlayerOverlap?: boolean;
  playerOverlapPenalty?: number;
  // Scoring format for badminton
  scoringFormat?: 'simple' | 'badminton';
  setsToWin?: number; // 1 (best of 1), 2 (best of 3), or 3 (best of 5)
  pointsPerSet?: number; // 11, 15, or 21
  deuceEnabled?: boolean; // Win by 2 in deuce (up to 30 for 21-point sets)
  // ---- Public TV display ------------------------------------------
  // How the public ``/display`` page renders the courts view.
  //
  //   strip — one tall row per court (default; best 3-6 courts, 1080p).
  //   grid  — 2-column responsive grid (best 8-16 courts).
  //   list  — dense one-line rows (best 16+ courts, side display).
  /** 'strip' is retired but still accepted from stored blobs — the board
   *  maps it to 'auto' on read (DC-1). New writes never send it. */
  tvDisplayMode?: 'auto' | 'strip' | 'grid' | 'list';
  // Brand accent for the public display — hex (``#RRGGBB``). Drives
  // the LIVE border, the LIVE pill, and the progress bar. Defaults to
  // emerald (``#10b981``) when unset.
  tvAccent?: string;
  // Display preset id — selects the substrate palette (bg/text/border)
  // for the public ``/display`` page. See displayPresets.ts for the
  // full list (court, pitch, midnight, ash, paper, chalk, daylight,
  // sand). Defaults to ``court`` when unset.
  tvPreset?: string;
  // Force a specific column count for grid mode. ``null`` / unset =
  // auto (1-2 columns based on viewport).
  tvGridColumns?: 1 | 2 | 3 | 4 | null;
  // Card size — overrides the auto-sizing strip/grid layouts.
  // ``auto`` keeps the current behaviour; ``compact`` shrinks padding;
  // ``comfortable`` is the default tall card; ``large`` expands for
  // big-room viewing.
  tvCardSize?: 'auto' | 'compact' | 'comfortable' | 'large';
  // Whether to show the live score on the public display. Off when
  // the venue prefers to keep scores private until the match ends.
  tvShowScores?: boolean;
  // Display layout configuration (UI-only; all optional).
  courtOrder?: number[] | null;
  hiddenCourts?: number[] | null;
  standingsMode?: 'off' | 'side' | 'rotate' | null;
  /** Board rotation (TV-7 / DC-3). `null` = every slide that has data.
   *  'side' and 'rotate' on standingsMode are equivalent now — the side
   *  panel is retired — and only 'off' still changes anything. */
  tvRotationSlides?: ('courts' | 'standings' | 'upNext')[] | null;
  tvRotationDwellSeconds?: number | null;
  // Optional event-column ordering and visibility for the Roster
  // position grid. Defaults to the canonical MD / WD / XD / WS / MS
  // sequence. Hidden columns are stored as ``false`` per rank.
  eventOrder?: string[];
  eventVisible?: Record<string, boolean>;
  // ---- Engine settings -------------------------------------------
  // Reproducible-run mode: solver runs single-threaded with a fixed
  // seed so the same input produces a byte-identical schedule across
  // runs. ~3× slower than parallel mode; default off.
  deterministic?: boolean;
  // Seed used in deterministic mode. Default 42 when unset.
  randomSeed?: number;
  // Solver wall-clock cap. The CP-SAT solver returns the best
  // feasible schedule found within this window. Higher = closer to
  // optimal at the cost of operator wait time. Default 30 s.
  solverTimeLimitSeconds?: number;
  // Director time-axis: minutes added to every unstarted match's
  // displayed wall-clock by `delay_start` actions. Solver still plans
  // on the abstract slot grid; this is purely a display offset.
  clockShiftMinutes?: number;
  // Court IDs (1-indexed) closed *all day* — the legacy shape kept
  // for backward compat with persisted state. New time-bounded
  // closures go into ``courtClosures`` below.
  closedCourts?: number[];
  // Time-bounded court closures. Each entry forbids the named
  // court inside its half-open ``[fromTime, toTime)`` window. Either
  // bound omitted means open-ended on that side; both omitted is
  // equivalent to a legacy ``closedCourts`` entry (full-day).
  courtClosures?: CourtClosure[];
  // Court policy (SP-COURT-1, ADR 0015). "pinned" (default) = the solver
  // promises a specific court per match; "queue" = the solver pools the
  // courts and solves for time only, courts assigned by colouring — how a
  // real desk runs the day. Per-court overrides let a show court stay
  // pinned inside a queue-mode venue. Keys are 1-indexed court ids.
  courtPolicy?: 'pinned' | 'queue';
  courtOverrides?: Record<number, 'pinned' | 'pool'>;
  // How many "on deck" matches the Run desk highlights (CP5, 1-5).
  // Default 3 — research says call the next 2-3 about ten minutes early.
  onDeckCount?: number;
  // How many near-optimal alternative schedules the solver keeps
  // alongside the chosen one. Operator can swap to a candidate in a
  // click when reality (overrun, withdrawal, court closure) makes
  // the chosen plan no longer fit — no re-solve needed. Default 5.
  candidatePoolSize?: number;
  /** Slots of forced rest between bracket rounds. Bracket-side only. */
  restBetweenRounds?: number;
}

export interface CourtClosure {
  courtId: number;
  /** HH:mm; omit for "from start of day". */
  fromTime?: string;
  /** HH:mm; omit for "until end of day". */
  toTime?: string;
  reason?: string;
}

export interface BreakWindow {
  start: string; // HH:mm format
  end: string; // HH:mm format
}

// Schedule Views
export type ScheduleView = 'timeslot' | 'court';

// Schedule
export interface ScheduleCandidate {
  solutionId: string;
  assignments: ScheduleAssignment[];
  objectiveScore: number;
  foundAtSeconds: number;
}

export interface ScheduleDTO {
  assignments: ScheduleAssignment[];
  unscheduledMatches: string[];
  softViolations: SoftViolation[];
  objectiveScore: number | null;
  infeasibleReasons: string[];
  status: 'optimal' | 'feasible' | 'infeasible' | 'unknown';
  /** Random seed the solver used. Pair with the Reproducible-run
   *  toggle to regenerate a byte-identical schedule. */
  solverSeed?: number;
  /** What the engine actually did (SP-COURT-1 CP8-v1): a queue-mode solve
   *  with closed-court windows falls back to "pinned" and says so here, so
   *  the Plan board can explain the grid instead of showing a call list the
   *  solve did not produce. Absent on pre-policy schedules = pinned. */
  effectivePolicy?: 'pinned' | 'queue';
  /** Top-N near-optimal alternatives the solver found while
   *  improving. ``assignments`` above mirrors
   *  ``candidates[activeCandidateIndex].assignments`` when set;
   *  callers should read via ``getActiveAssignments(schedule)`` to
   *  honour the active selection without crashing on legacy
   *  schedules where these fields are missing. */
  candidates?: ScheduleCandidate[];
  activeCandidateIndex?: number;
}

export interface ScheduleAssignment {
  matchId: string;
  slotId: number;
  courtId: number;
  durationSlots: number;
}

export interface SoftViolation {
  type: string;
  matchId?: string | null;
  playerId?: string | null;
  description: string;
  penaltyIncurred: number;
}

// Set score for badminton matches
export interface SetScore {
  sideA: number;
  sideB: number;
}

// Delay reason options
type DelayReason = 'player_not_present' | 'injury' | 'court_issue' | 'other';

// Player confirmation entry for tracking who caused a delay
// Match State (for Match Desk operations)
export interface MatchStateDTO {
  matchId: string;
  status: 'scheduled' | 'called' | 'started' | 'finished';
  /** ISO-8601 UTC timestamp, e.g. "2026-04-19T18:05:37.000Z".
   *  Set the first time a match transitions to `called`. Used to show
   *  "Called Xm ago" and as an audit point in the match details. */
  calledAt?: string;
  /** ISO-8601 UTC timestamp, e.g. "2026-04-19T18:05:37.000Z".
   *  Parsed via `parseMatchStartMs` on both live-ops and TV readers.
   *  Legacy "HH:MM" values are tolerated for one release cycle. */
  actualStartTime?: string;
  /** ISO-8601 UTC timestamp — see `actualStartTime`. */
  actualEndTime?: string;
  actualCourtId?: number; // Override court if different from scheduled
  actualSlotId?: number; // Live slot override (set from command response time_slot)
  originalSlotId?: number; // Original scheduled slot before being pushed
  originalCourtId?: number; // Original scheduled court before being pushed
  delayed?: boolean; // Explicitly marked as delayed
  delayReason?: DelayReason; // Reason for delay
  delayedPlayerId?: string; // Which player caused the delay (for tracking)
  postponed?: boolean; // Match is postponed to later
  pinned?: boolean; // Pinned to court/time (for finals/special matches)
  playerConfirmations?: Record<string, boolean>; // Player ID -> confirmed at court
  score?: {
    sideA: number;
    sideB: number;
  };
  sets?: SetScore[]; // For badminton set-by-set scoring
  notes?: string;
  updatedAt?: string;
}

// Roster Group (for school grouping)
export interface RosterGroupDTO {
  id: string;
  name: string;
  type?: 'group' | 'roster';
  parentId?: string | null;
  children?: string[]; // child group IDs
  playerIds?: string[]; // player IDs (for roster type)
  metadata?: {
    description?: string;
    color?: string;
    [key: string]: any;
  };
}

// Withdrawal reason
type WithdrawalReason = 'injury' | 'no_show' | 'disqualification' | 'personal' | 'other';

// Player
export interface PlayerDTO {
  id: string; // Auto-generated UUID
  name: string;
  groupId: string; // School group ID (REQUIRED - this is school vs school scheduling)
  ranks?: string[]; // [MS1, MD1, XD1] - Player can play multiple events
  availability: AvailabilityWindow[];
  minRestMinutes?: number | null; // If not provided, uses tournament config's defaultRestMinutes
  notes?: string;
  status?: 'active' | 'withdrawn'; // Player status - defaults to 'active'
  withdrawalReason?: WithdrawalReason; // Reason if withdrawn
  withdrawnAt?: string; // Timestamp when withdrawn
  /** Entries provenance (SP-E1-1, spec §5 Seam A) — the `entries.id` this
   *  player was materialized from. Half of the seam's back-reference pair
   *  (`entries.committed_player_id` is the other half). Declared here because
   *  the backend `PlayerDTO` is a StrictModel: an undeclared key is REFUSED
   *  (422), so the autosave PUT must carry the field by name or the whole
   *  blob write fails once a committed player is in the roster. */
  sourceEntryId?: string;
  /** R-DM-2(a) — the person key. `sourceEntryId` points at ONE entry; this
   *  points at the HUMAN, who routinely holds several. Same value the
   *  `entry-{uuid}` id encodes, typed instead of parsed out of a prefix.
   *  Declared here for the same StrictModel reason as `sourceEntryId`. */
  entryPlayerId?: string;
  /** Other confirmed Meet doubles partners, keyed by bare division. */
  partnerPlayerIds?: Record<string, string>;
  /** The entrant's own free-text availability sentence, carried verbatim from
   *  `entries.remarks`. Deliberately NOT `notes` — that is the operator's own
   *  field, and overwriting it would destroy what the operator wrote and lose
   *  the attribution. Never parsed, never fed to the solver. */
  remarks?: string;
}

export interface AvailabilityWindow {
  start: string; // HH:mm format
  end: string; // HH:mm format
}

/** Roster entry for bracket-kind tournaments. */
export interface BracketPlayerDTO {
  id: string;
  name: string;
  notes?: string;
  /** Per-player rest override in slots; unset = session `defaultRestSlots`. */
  restSlots?: number;
  /** POSITIVE (allowed) HH:mm windows — empty/unset means available all
   *  day. Mirrors the backend `BracketPlayerDTO.availability` (SP-D7 S2),
   *  which threads it into the CP-SAT solve via player_constraints. */
  availability?: AvailabilityWindow[];
  /** Entries provenance — mirrors `PlayerDTO`. The Bracket half of Seam A
   *  writes the `bracket_participants` row *and* this blob entry, because the
   *  participant table has nowhere to put a remark. */
  sourceEntryId?: string;
  /** R-DM-2(a) — the person key, mirroring `PlayerDTO`. Also stored as
   *  `bracket_participants.entry_player_id`; this blob copy is what the
   *  roster/availability surfaces read. */
  entryPlayerId?: string;
  remarks?: string;
}

