// Multi-tournament CRUD (Step 2; widened in Step 6)
export type TournamentStatus = 'draft' | 'active' | 'archived';

export type TournamentRole = 'owner' | 'operator' | 'viewer';

/** Top-level kind of event a tournament row represents. ``meet`` is
 *  the intercollegiate dual / tri-meet workflow (Setup / Roster /
 *  Matches / Schedule / Live / TV tabs); ``bracket`` is a single-
 *  elimination or round-robin draw (BracketTab surface only, meet
 *  tabs hidden). User-facing copy calls ``bracket`` a "Tournament";
 *  the wire-format keeps ``bracket`` for code symmetry with the
 *  bracket_* table family. */
type TournamentKind = 'meet' | 'bracket';

/** A persisted workspace module (from the backend `workspace_modules` table).
 *  Statuses: enabled | available | disabled | coming_soon. All modules are fully
 *  built, so `coming_soon` is legacy/defensive only — the frontend maps any such
 *  value to `available` in `modulesFromDto` (it never renders a "coming soon" state). */
export interface WorkspaceModuleDTO {
  /** `entries` is CLOUD-ONLY (SP-E1-1 ruling D2): the backend seeds and returns
   *  the row only when `AUTH_MODE=cloud`, so a local-mode workspace never sees
   *  it here. The union carries it because the wire can. */
  moduleId: 'meet' | 'bracket' | 'display' | 'entries';
  status: 'enabled' | 'available' | 'disabled' | 'coming_soon';
  config: Record<string, unknown> | null;
  /** Whether this module owns operational data (matches, draws). Disabling
   *  such a module 409s, and the catalog says so BEFORE the click (WSMOD-2).
   *  Server-computed; optional for older payloads. */
  hasData?: boolean;
}

// ---- Entries (SP-E1-1) ------------------------------------------------

/** The entry lifecycle vocabulary (spec §6). E1 only ever *produces*
 *  `pending` → `confirmed` (ruling D1 — submissions skip `unverified` until
 *  E2's email verification ships, and reject/promote/withdraw are E2), but the
 *  desk must render whatever the backend hands it, so the full set is typed. */
export type EntryState =
  | 'unverified'
  | 'pending'
  | 'confirmed'
  | 'rejected'
  | 'waitlisted'
  | 'withdrawn';

/** One row of the operator's entries desk — mirrors the backend
 *  `EntryDeskRowDTO`, which is a PROJECTION rather than the table: the
 *  doubles columns are deliberately absent, and so is every piece of
 *  entrant credential material. (This comment used to name
 *  `manage_token_hash` as the thing being withheld; ruling R10 deleted
 *  that column outright — managing an entry is login-gated "my entries"
 *  now, and the material to keep off this screen is the account's
 *  password hash and session token.)
 *
 *  There is no separate `flags` field on the wire. The R7 soft-duplicate
 *  signal is the `needs_review` member of `pendingReasons` — one list, one
 *  source of truth; a parallel flags array would be a second place for the
 *  same fact to disagree with itself. */
export interface EntryDTO {
  id: string;
  entryEventId: string;
  /** Denormalized from `entry_events.code` — the same string the commit seam
   *  turns into `ranks[]`. Null when the event row is missing. */
  eventCode: string | null;
  state: EntryState;
  /** Reason codes: `awaiting_partner` | `awaiting_payment` | `over_cap` |
   *  `needs_review` | `gender_mismatch`. The last is an ENTRY-level reason
   *  on the `needs_review` precedent (SP-E1-2 Phase A), deliberately not
   *  one of the workspace attention codes — a different vocabulary read by
   *  a different surface. */
  pendingReasons: string[];
  /** The act this entry arrived on (R13). `contactName` / `contactEmail`
   *  used to be fields on this row; they are one hop out now, because "who
   *  to write to about this" belongs to the submission and a desk that
   *  repeated it per entry showed one address three times for one form.
   *  Null only in the shape the type allows and the writer never
   *  produces — see the backend DTO. */
  submission: EntrySubmissionDTO | null;
  playerName: string;
  /** The resolved person (R-P7c): `entry_players.id`. The key one human's
   *  entries share across submissions — the desk's grouping identity, where
   *  before it had only `playerName` and eyes. Null on rows minted before
   *  the person spine. */
  entryPlayerId: string | null;
  /** The other half of this doubles pair (`entries.partner_entry_id`),
   *  written on BOTH halves at acceptance. Null for singles and for a
   *  nomination nobody has accepted. The partner's NAME is a join the desk
   *  already holds every row for — F-DM-35 was the key not being on the
   *  wire, not the name. */
  partnerEntryId: string | null;
  remarks: string | null;
  listOptOut: boolean;
  /** Set once Seam A has materialized this entry as a roster player. */
  committedPlayerId: string | null;
  submittedAt: string | null;
  withdrawnAt: string | null;
}

/** One form act, as much of it as the desk needs — mirrors the backend
 *  `EntrySubmissionDTO`.
 *
 *  `id` is the GROUPING KEY: the desk bands entries by it to show "these
 *  arrived on one form", which before R13 an operator had to infer by eye
 *  from a repeated email address — ambiguous exactly when it mattered,
 *  because one parent account legitimately submits many times.
 *
 *  `feeTotalCents` belongs to the act and not to any entry under it:
 *  tiered pricing prices the person, not the event, so three events for
 *  one player have one total between them rather than three. */
export interface EntrySubmissionDTO {
  id: string;
  accountEmail: string | null;
  accountName: string | null;
  feeTotalCents: number | null;
  submittedAt: string | null;
}

/** One committed entry: which entry became which roster player. */
export interface EntryCommitOutcomeDTO {
  id: string;
  playerId: string;
}

/** One skipped entry + the stable reason code. Spec §5: partial success is
 *  reported per-entry, not rolled back — so this is a normal outcome, not an
 *  error body. Codes: `UNMAPPABLE_EVENT` | `DRAW_NOT_EDITABLE` |
 *  `STATE_CONFLICT` | `INVALID_PLAYER`. */
export interface EntrySkipDTO {
  id: string;
  reason: string;
}

export interface EntryCommitResultDTO {
  committed: EntryCommitOutcomeDTO[];
  skipped: EntrySkipDTO[];
}

/** Server-computed control-plane signals (mirrors backend
 *  `api/workspace_signals.py`). Surfaced on `TournamentSummaryDTO.signals`. */
export interface AttentionReasonDTO {
  /** Stable machine code, e.g. "NO_ROSTER". */
  code: string;
  /** Human label, e.g. "No players added yet". */
  label: string;
}

interface ModuleCountsDTO {
  enabled: number;
  available: number;
  disabled: number;
  comingSoon: number;
}

interface CollaborationDTO {
  memberCount: number;
  activeInviteCount: number;
}

/** The inspector's metric triplet (`to do` = attention-reason count). */
interface MatchMetricsDTO {
  total: number;
  scheduled: number;
  toDo: number;
  /** Terminally-resolved matches (finished/retired; bracket: recorded
   *  results) — the Overview's live-progress readout. Optional for older
   *  payloads. */
  played?: number;
  /** Matches on a court right now (started; called deliberately excluded —
   *  its players are still walking). INS-4/OV-4. Optional for older payloads. */
  playing?: number;
  /** Courts with nothing playing on them. `null` when the workspace has no
   *  court count to subtract from — an unknown is not zero. */
  courtsFree?: number | null;
}

/** One upcoming match for the inspector's "Next up" list. `status` is
 *  schedule-derivable only ("scheduled") — live called/started state is not
 *  surfaced on the Hub (it lives in match_states; Operations Run is live). */
export interface NextMatchDTO {
  code: string;
  timeLabel: string | null;
  courtLabel: string | null;
  status: string;
  /** Identity, so a "Up next" row can be a door rather than a readout (OV-1).
   *  `source` matters as much as the id: Operations keys selection
   *  `{source}:{id}` because meet and bracket records are non-merged
   *  (ADR 0006). Optional for older payloads. */
  matchId?: string | null;
  source?: 'meet' | 'bracket' | null;
}

export interface WorkspaceSignalsDTO {
  health: 'good' | 'attention' | 'draft' | 'archived';
  attention: AttentionReasonDTO[];
  modules: ModuleCountsDTO;
  /** Per-kind readiness checklist (keys vary by kind), e.g. `{ roster: true }`. */
  setup: Record<string, boolean>;
  collaboration: CollaborationDTO;
  /** Per-workspace match metrics (redesign). Optional for older payloads. */
  matches?: MatchMetricsDTO;
  /** Next ≤3 upcoming matches (finished/on-court ones are filtered
   *  server-side since the 2026-07-09 audit). Optional / empty when none. */
  nextUp?: NextMatchDTO[];
  /** Lifecycle phase derived from real play state (2026-07-09 audit):
   *  setup → ready → live → complete. Optional for older payloads. */
  /** E4: the entries desk in numbers. Absent where there is no entry page,
   *  which is every local-mode workspace (invariant I3). Counts only — this
   *  rides on a summary the Hub renders for every workspace at once, and a
   *  control-plane payload carrying entrant data would be a disclosure
   *  surface with no route of its own to review. */
  entries?: {
    total: number;
    pending: number;
    waitlisted: number;
    confirmed: number;
    /** `confirmed` and not yet on the roster — what ENTRIES_NOT_COMMITTED
     *  counts, so the panel can say how many rather than only that there
     *  are some. */
    uncommitted: number;
    closed: boolean;
  } | null;
  // E4 (program Phase 9): three entries phases at the FRONT; the four play
  // phases keep their exact meanings. A workspace with no entry page never
  // reaches the first three.
  phase?:
    | 'announced'
    | 'entries_open'
    | 'entries_review'
    | 'setup'
    | 'ready'
    | 'live'
    | 'complete';
}

export interface TournamentSummaryDTO {
  id: string;
  name: string | null;
  status: TournamentStatus;
  kind: TournamentKind;
  tournamentDate: string | null;
  tournamentEndDate?: string | null;
  timeZone?: string;
  createdAt: string;
  updatedAt: string;
  /** Caller's role on this tournament — non-null in list responses
   *  because the list is filtered to the caller's memberships. */
  role: TournamentRole | null;
  /** Owner's email, denormalised at tournament-create time. Used by
   *  the "Shared with You" dashboard section. */
  ownerName: string | null;
  /** Persisted module catalog for this workspace (sub-project #1). Optional
   *  for backward compatibility with older payloads. */
  modules?: WorkspaceModuleDTO[];
  /** Server-computed control-plane signals (SP-A). Optional for backward
   *  compatibility with older payloads. */
  signals?: WorkspaceSignalsDTO;
}

export interface TournamentCreateDTO {
  name?: string | null;
  kind?: TournamentKind;
  tournamentDate?: string | null;
  tournamentEndDate?: string | null;
  timeZone?: string;
  courtCount?: number;
  /** Optional explicit module seed (control-plane templates). When present,
   *  the backend persists this set instead of the kind-derived one. */
  modules?: WorkspaceModuleDTO[];
}

export interface TournamentUpdateDTO {
  name?: string | null;
  status?: TournamentStatus;
  tournamentDate?: string | null;
  tournamentEndDate?: string | null;
  timeZone?: string;
}

