// Invite links (Step 7)
export type InviteRole = 'operator' | 'viewer';

export interface InviteCreateDTO {
  role: InviteRole;
  /** SP-CLOUD-2: when set, this becomes an email invite — the link is
   *  delivered via the email seam and the invite expires. */
  email?: string;
}

export interface InviteCreatedDTO {
  token: string;
  /** Relative path — frontend prepends ``window.location.origin``. */
  url: string;
  tournamentId: string;
  role: InviteRole;
  createdAt: string;
  /** Recipient address for email invites; null for bare links. */
  email?: string | null;
}

export interface InviteSummaryDTO {
  token: string;
  tournamentId: string;
  role: InviteRole;
  createdAt: string;
  expiresAt: string | null;
  revokedAt: string | null;
  valid: boolean;
  /** Recipient address for email invites; null for bare links. */
  email?: string | null;
}

/** Public `GET /invites/{token}`. A 200 *means* the invite is
 *  acceptable — every other state (unknown, revoked, expired, workspace
 *  deleted) answers one uniform 404, so there are no lifecycle flags to
 *  read here. `InviteSummaryDTO` keeps them for the owner-facing
 *  listing, which is authenticated and may legitimately see them. */
export interface InviteResolveDTO {
  token: string;
  tournamentId: string;
  tournamentName: string | null;
  role: InviteRole;
}

export interface InviteAcceptedDTO {
  tournamentId: string;
  role: string;
  alreadyMember: boolean;
}

export interface TournamentMemberDTO {
  userId: string;
  role: string;
  joinedAt: string;
  /** SP-CLOUD-2: real identity from the users table. ``email`` is null
   *  for pre-account placeholder identities (unmigrated rows). */
  email?: string | null;
  displayName?: string | null;
}

// ---- Operator commands (Step F of the architecture-adjustment arc) -------

type MatchAction =
  | 'call_to_court'
  | 'start_match'
  | 'finish_match'
  | 'retire_match'
  | 'uncall'
  | 'assign_court'
  | 'postpone_match';

/**
 * Body of ``POST /tournaments/{tid}/commands``. The ``id`` is the
 * client-generated UUID used as the idempotency key; the same id
 * resubmitted gets the original outcome.
 */
export interface CommandRequestDTO {
  id: string;
  match_id: string;
  action: MatchAction;
  payload: Record<string, unknown> | null;
  seen_version: number;
}

/**
 * Successful (200) response body — carries the *current* match
 * state. Replay after a third-party update returns the current
 * (mutated) state, not the post-original-apply state.
 */
export interface CommandResponseDTO {
  command_id: string;
  match_id: string;
  status: 'scheduled' | 'called' | 'playing' | 'finished' | 'retired';
  version: number;
  court_id: number | null;
  time_slot: number | null;
  applied_at: string;
  replay: boolean;
}

/**
 * Body shape for 409 (state-machine conflict or stale version).
 * ``error`` discriminates between the two flavours; the frontend
 * branches on it to choose between "refetch and retry" and "show
 * permanent rejection."
 */
export interface CommandConflictDTO {
  error: 'conflict' | 'stale_version';
  match_id: string;
  message: string;
  current_status?: string;
  attempted_status?: string;
  current_version?: number;
  seen_version?: number;
}

// Constraint Visualization Types
export interface ConstraintViolation {
  type: 'rest' | 'overlap' | 'availability' | 'court_capacity' | 'game_proximity_min' | 'game_proximity_max';
  severity: 'hard' | 'soft';
  playerIds: string[];
  matchIds: string[];
  description: string;
}
